"""Min-plus multiplicativity: eval(P (x) Q) = eval(P) + eval(Q)."""
from __future__ import annotations
from fractions import Fraction
from itertools import product
from typing import Sequence

class TropPoly:
    def __init__(self, monomials):
        self.monomials = list(monomials)
        self.n = len(monomials[0][1])
    def eval(self, x: Sequence[Fraction]) -> Fraction:
        return min(c + sum(e[k]*x[k] for k in range(self.n))
                   for c, e in self.monomials)
    def mul(self, other: "TropPoly") -> "TropPoly":
        return TropPoly([(c1+c2, tuple(e1[k]+e2[k] for k in range(self.n)))
                         for (c1,e1),(c2,e2) in product(self.monomials, other.monomials)])

if __name__ == "__main__":
    F = Fraction
    P = TropPoly([(F(0),(F(0),F(0))), (F(1),(F(1),F(0))), (F(2),(F(0),F(1)))])
    Q = TropPoly([(F(0),(F(0),F(0))), (F(3),(F(1),F(0))), (F(1),(F(0),F(1)))])
    PQ = P.mul(Q)
    for x in [(F(0),F(0)), (F(1),F(2)), (F(-3),F(5))]:
        assert PQ.eval(x) == P.eval(x) + Q.eval(x)
    print("eval(P (x) Q) = eval(P) + eval(Q) verified.")

